/**
 * Shared UI kit. OWNED BY THE LEAD — module agents import from "@/components/ui" and do not edit this file.
 * If you need a primitive that isn't here, build it inside your module's own components folder.
 *
 * All components are server-safe (no hooks) so they work in Server Components and forms with server actions.
 */
import Link from "next/link";
import type { ComponentProps, ReactNode } from "react";
import { humanize, statusTone } from "@/lib/status";

const cx = (...c: (string | false | null | undefined)[]) => c.filter(Boolean).join(" ");

/* ── Page structure ── */

export function PageHeader({
  title, description, actions, back,
}: { title: ReactNode; description?: ReactNode; actions?: ReactNode; back?: { href: string; label: string } }) {
  return (
    <header className="mb-6 flex flex-wrap items-end justify-between gap-4 pt-8 md:pt-0">
      <div className="min-w-0">
        {back && (
          <Link href={back.href} className="mb-1 inline-block text-sm text-muted hover:text-primary">
            ‹ {back.label}
          </Link>
        )}
        <h1 className="text-2xl font-bold tracking-tight text-ink">{title}</h1>
        {description && <p className="mt-1 max-w-3xl text-[15px] text-muted">{description}</p>}
      </div>
      {actions && <div className="flex flex-wrap items-center gap-2">{actions}</div>}
    </header>
  );
}

export function Panel({
  title, actions, children, className, padded = true,
}: { title?: ReactNode; actions?: ReactNode; children: ReactNode; className?: string; padded?: boolean }) {
  return (
    <section className={cx("rounded-[var(--radius-panel)] border border-line bg-surface", className)}>
      {(title || actions) && (
        <div className="flex items-center justify-between gap-3 border-b border-line px-4 py-3">
          {title && <h2 className="text-[15px] font-semibold">{title}</h2>}
          {actions && <div className="flex items-center gap-2">{actions}</div>}
        </div>
      )}
      <div className={padded ? "p-4" : undefined}>{children}</div>
    </section>
  );
}

/** Small key figure. Use sparingly — a row of 3–5 at the top of a dashboard, not everywhere. */
export function Stat({ label, value, hint, href }: { label: string; value: ReactNode; hint?: ReactNode; href?: string }) {
  const body = (
    <>
      <p className="text-sm text-muted">{label}</p>
      <p className="mt-1 text-2xl font-bold">{value}</p>
      {hint && <p className="mt-0.5 text-xs text-muted">{hint}</p>}
    </>
  );
  const cls = "block rounded-[var(--radius-panel)] border border-line bg-surface px-4 py-3";
  return href ? <Link href={href} className={cx(cls, "hover:border-primary")}>{body}</Link> : <div className={cls}>{body}</div>;
}

export function EmptyState({ title, children, action }: { title: string; children?: ReactNode; action?: ReactNode }) {
  return (
    <div className="rounded-[var(--radius-panel)] border border-dashed border-line bg-surface px-6 py-10 text-center">
      <p className="font-semibold">{title}</p>
      {children && <p className="mx-auto mt-1 max-w-md text-sm text-muted">{children}</p>}
      {action && <div className="mt-4 flex justify-center">{action}</div>}
    </div>
  );
}

/* ── Buttons ── */

type Variant = "primary" | "secondary" | "ghost" | "danger";
const btn: Record<Variant, string> = {
  primary: "bg-primary text-white hover:bg-primary-strong border-primary",
  secondary: "bg-surface text-ink border-line hover:bg-sunken",
  ghost: "bg-transparent text-primary border-transparent hover:bg-primary-soft",
  danger: "bg-surface text-danger border-line hover:bg-danger-soft",
};
const btnBase =
  "inline-flex items-center justify-center gap-1.5 rounded-[var(--radius-control)] border px-3 py-1.5 text-sm font-semibold whitespace-nowrap disabled:opacity-50 disabled:pointer-events-none";

export function Button({ variant = "primary", className, ...p }: ComponentProps<"button"> & { variant?: Variant }) {
  return <button type="submit" {...p} className={cx(btnBase, btn[variant], className)} />;
}

export function LinkButton({ variant = "secondary", className, ...p }: ComponentProps<typeof Link> & { variant?: Variant }) {
  return <Link {...p} className={cx(btnBase, btn[variant], className)} />;
}

/* ── Form controls ── */

const control =
  "w-full rounded-[var(--radius-control)] border border-line bg-surface px-2.5 py-1.5 text-[14px] text-ink placeholder:text-faint focus:border-primary focus:outline-none";

export function Field({ label, hint, error, children, className }: {
  label: string; hint?: ReactNode; error?: string; children: ReactNode; className?: string;
}) {
  return (
    <label className={cx("block", className)}>
      <span className="mb-1 block text-sm font-semibold text-ink">{label}</span>
      {children}
      {hint && !error && <span className="mt-1 block text-xs text-muted">{hint}</span>}
      {error && <span className="mt-1 block text-xs text-danger">{error}</span>}
    </label>
  );
}

export function Input({ className, ...p }: ComponentProps<"input">) {
  return <input {...p} className={cx(control, className)} />;
}

export function Textarea({ className, ...p }: ComponentProps<"textarea">) {
  return <textarea rows={3} {...p} className={cx(control, className)} />;
}

export function Select({ className, options, placeholder, ...p }: ComponentProps<"select"> & {
  options: { value: string | number; label: string }[]; placeholder?: string;
}) {
  return (
    <select {...p} className={cx(control, "pr-8", className)}>
      {placeholder !== undefined && <option value="">{placeholder}</option>}
      {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

/** Responsive grid for forms: <FormGrid cols={3}>…fields…</FormGrid> */
export function FormGrid({ cols = 2, children }: { cols?: 1 | 2 | 3 | 4; children: ReactNode }) {
  const c = { 1: "", 2: "sm:grid-cols-2", 3: "sm:grid-cols-2 lg:grid-cols-3", 4: "sm:grid-cols-2 lg:grid-cols-4" }[cols];
  return <div className={cx("grid grid-cols-1 gap-4", c)}>{children}</div>;
}

/* ── Tables ── */

export function Table({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <div className={cx("overflow-x-auto rounded-[var(--radius-panel)] border border-line bg-surface", className)}>
      <table className="w-full border-collapse text-[14px]">{children}</table>
    </div>
  );
}
export function THead({ children }: { children: ReactNode }) {
  return <thead className="bg-sunken text-left text-[13px] text-muted">{children}</thead>;
}
export function Th({ children, className, align }: { children?: ReactNode; className?: string; align?: "right" | "center" }) {
  return (
    <th className={cx("whitespace-nowrap border-b border-line px-3 py-2 font-semibold", align === "right" && "text-right", align === "center" && "text-center", className)}>
      {children}
    </th>
  );
}
export function Td({ children, className, align, colSpan }: {
  children?: ReactNode; className?: string; align?: "right" | "center"; colSpan?: number;
}) {
  return (
    <td colSpan={colSpan} className={cx("border-b border-line px-3 py-2 align-top", align === "right" && "text-right", align === "center" && "text-center", className)}>
      {children}
    </td>
  );
}

/* ── Badges ── */

import type { Tone } from "@/lib/status";
export type { Tone };
const tones: Record<Tone, string> = {
  neutral: "bg-sunken text-muted",
  primary: "bg-primary-soft text-primary-strong",
  ok: "bg-ok-soft text-ok",
  warn: "bg-warn-soft text-warn",
  danger: "bg-danger-soft text-danger",
  info: "bg-info-soft text-info",
  tag: "bg-tag-soft text-warn",
};
export function Badge({ tone = "neutral", children }: { tone?: Tone; children: ReactNode }) {
  return (
    <span className={cx("inline-flex items-center rounded px-1.5 py-0.5 text-xs font-semibold whitespace-nowrap", tones[tone])}>
      {children}
    </span>
  );
}

/** Badge for any enum status value — colours come from src/lib/status.ts. */
export function StatusBadge({ value }: { value: string | null | undefined }) {
  return <Badge tone={statusTone(value)}>{humanize(value)}</Badge>;
}

/* ── Misc ── */

/** Definition list for detail pages. */
export function Details({ items }: { items: { label: string; value: ReactNode }[] }) {
  return (
    <dl className="grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2 lg:grid-cols-3">
      {items.map((i) => (
        <div key={i.label}>
          <dt className="text-xs text-muted">{i.label}</dt>
          <dd className="mt-0.5 text-[14px]">{i.value ?? <span className="text-faint">—</span>}</dd>
        </div>
      ))}
    </dl>
  );
}

/** Tabs rendered as links (?tab=...), so they work without client JS. */
export function TabLinks({ tabs, active }: { tabs: { href: string; label: string; key: string }[]; active: string }) {
  return (
    <div className="mb-5 flex gap-1 overflow-x-auto border-b border-line">
      {tabs.map((t) => (
        <Link
          key={t.key}
          href={t.href}
          aria-current={t.key === active ? "page" : undefined}
          className={cx(
            "-mb-px whitespace-nowrap border-b-2 px-3 py-2 text-sm",
            t.key === active ? "border-primary font-semibold text-primary-strong" : "border-transparent text-muted hover:text-ink",
          )}
        >
          {t.label}
        </Link>
      ))}
    </div>
  );
}

export { cx };
